using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using Newtonsoft.Json;
public static class BlueWispFinalState {
 const string Root="Assets/PixelFX/BlueWisp/V3/";
 public static string Run(){
  var scene=SceneManager.GetActiveScene();if(Application.isPlaying||Application.dataPath!="/Users/user/Desktop/VFXDemo/VFXDemo/Assets"||scene.path!="Assets/Scenes/VFXWorkbench.unity")throw new Exception("Wrong target/state");
  var roots=scene.GetRootGameObjects();if(roots.Any(g=>g.name.Contains("Temporary")||g.name.Contains("FrameProbe")))throw new Exception("Temporary object remains");
  var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"Prefabs/VFX_BlueWisp_V3_Loop.prefab");var instance=roots.Single(g=>g.name=="VFX_BlueWisp_V3_Loop");var shader=AssetDatabase.LoadAssetAtPath<Shader>(Root+"Shaders/BlueWispNative.shader");
  // Space only this newly imported sample away from the existing CyberOrb path.
  if(!scene.isDirty&&instance.transform.position==new Vector3(-4,2.1f,0)){
   var before=roots.Where(g=>g!=instance).SelectMany(g=>g.GetComponentsInChildren<Component>(true)).Where(c=>c!=null).Select(c=>new{c,json=EditorJsonUtility.ToJson(c)}).ToArray();
   Undo.RecordObject(instance.transform,"Space BlueWisp sample");instance.transform.position=new Vector3(-6,2.1f,0);PrefabUtility.RecordPrefabInstancePropertyModifications(instance.transform);
   if(before.Any(x=>x.c==null||EditorJsonUtility.ToJson(x.c)!=x.json))throw new Exception("Existing component changed; not saving scene.");
   Undo.FlushUndoRecordObjects();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
  }
  Func<GameObject,object> describe=g=>new{components=g.GetComponentsInChildren<Component>(true).Select(c=>c==null?"MISSING":c.GetType().Name).Distinct(),systems=g.GetComponentsInChildren<ParticleSystem>().Select(p=>{var r=p.GetComponent<ParticleSystemRenderer>();var streams=new System.Collections.Generic.List<ParticleSystemVertexStream>();r.GetActiveVertexStreams(streams);return new{p.name,duration=p.main.duration,lifetime=p.main.startLifetime.constant,loop=p.main.loop,playOnAwake=p.main.playOnAwake,maxParticles=p.main.maxParticles,emission=p.emission.enabled,bursts=p.emission.burstCount,speed=p.main.startSpeed.constant,size=p.main.startSize.constant,autoSeed=p.useAutoRandomSeed,sheet=p.textureSheetAnimation.enabled,lights=p.lights.enabled,alignment=r.alignment.ToString(),mesh=AssetDatabase.GetAssetPath(r.mesh),material=AssetDatabase.GetAssetPath(r.sharedMaterial),streams=streams.Select(s=>s.ToString()).ToArray()};}).ToArray()};
  bool componentsOk=prefab.GetComponentsInChildren<Component>(true).All(c=>c is Transform||c is ParticleSystem||c is ParticleSystemRenderer);bool nativeOk=prefab.GetComponentsInChildren<ParticleSystem>().All(p=>p.main.loop&&Mathf.Abs(p.main.duration-.28f)<1e-6&&Mathf.Abs(p.main.startLifetime.constant-.28f)<1e-6&&p.emission.enabled&&!p.textureSheetAnimation.enabled&&!p.lights.enabled&&p.main.maxParticles==1);
  var report=new{success=!scene.isDirty&&componentsOk&&nativeOk&&shader.isSupported&&!ShaderUtil.ShaderHasError(shader),dataPath=Application.dataPath,product=Application.productName,scene=scene.path,dirty=scene.isDirty,playing=Application.isPlaying,paused=EditorApplication.isPaused,background=Application.runInBackground,roots=roots.Select(g=>new{g.name,active=g.activeSelf,position=g.transform.position.ToString(),scale=g.transform.localScale.ToString()}),prefab=describe(prefab),instance=describe(instance),shaderSupported=shader.isSupported,shaderErrors=ShaderUtil.GetShaderMessages(shader).Select(m=>m.message).ToArray(),componentsOk,nativeOk};
  var dir=Path.Combine(Directory.GetParent(Application.dataPath).FullName,"VFXWork/Previews/BlueWisp/V3");File.WriteAllText(Path.Combine(dir,"FinalState.json"),JsonConvert.SerializeObject(report,Formatting.Indented));Selection.activeGameObject=instance;if(SceneView.lastActiveSceneView!=null)SceneView.lastActiveSceneView.Frame(new Bounds(instance.transform.position,Vector3.one*4.8f),true);return JsonConvert.SerializeObject(new{report.success,report.scene,report.dirty,report.componentsOk,report.nativeOk,report.shaderErrors,roots=roots.Select(g=>g.name)});
 }
}
